<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;
Auth::requireAdmin();$pdo=Database::connection();$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$error='';$notice='';
function tsRound(PDO $p,int $id):array{$s=$p->prepare('SELECT r.*,e.name event_name FROM bdc_test_scoring_rounds r JOIN bdc_test_events e ON e.id=r.event_id WHERE r.id=:id');$s->execute(['id'=>$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Test round not found.');return$r;}
function tsHeats(PDO $p,array $round,int $judgeId):void{$roles=$p->prepare("SELECT DISTINCT e.dance_role FROM bdc_test_scoring_entries e JOIN bdc_test_scoring_judges j ON j.id=:j WHERE e.round_id=:r AND e.entry_status='active' AND (j.scoring_scope='all' OR j.scoring_scope=e.dance_role)");$roles->execute(['j'=>$judgeId,'r'=>$round['id']]);$p->prepare('DELETE FROM bdc_test_scoring_marks WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$round['id'],'j'=>$judgeId]);$ins=$p->prepare("INSERT INTO bdc_test_scoring_marks(round_id,entry_id,judge_id,mark_type,alt_rank,weighted_score,updated_by) VALUES(:r,:e,:j,:t,:a,:w,NULL)");foreach($roles->fetchAll(PDO::FETCH_COLUMN) as $role){$s=$p->prepare("SELECT id FROM bdc_test_scoring_entries WHERE round_id=:r AND dance_role=:role AND entry_status='active' ORDER BY id");$s->execute(['r'=>$round['id'],'role'=>$role]);$ids=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));shuffle($ids);$yes=min((int)$round['yes_count'],count($ids));for($i=0;$i<$yes;$i++)$ins->execute(['r'=>$round['id'],'e'=>$ids[$i],'j'=>$judgeId,'t'=>'yes','a'=>null,'w'=>$round['yes_weight']]);$cursor=$yes;foreach([1=>'alt1_weight',2=>'alt2_weight',3=>'alt3_weight'] as $alt=>$weight){if(isset($ids[$cursor])){$ins->execute(['r'=>$round['id'],'e'=>$ids[$cursor++],'j'=>$judgeId,'t'=>'alt','a'=>$alt,'w'=>$round[$weight]]);}}}}
function tsFinal(PDO $p,array $round,int $judgeId):void{$s=$p->prepare("SELECT id FROM bdc_test_scoring_final_pairs WHERE round_id=:r AND pairing_status='confirmed' ORDER BY pair_number");$s->execute(['r'=>$round['id']]);$pairs=array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));if(!$pairs)throw new RuntimeException('Confirm Final pairing first.');$ranks=range(1,count($pairs));shuffle($ranks);$p->prepare('DELETE FROM bdc_test_scoring_final_marks WHERE round_id=:r AND judge_id=:j')->execute(['r'=>$round['id'],'j'=>$judgeId]);$ins=$p->prepare('INSERT INTO bdc_test_scoring_final_marks(round_id,pair_id,judge_id,rank_value,updated_by) VALUES(:r,:p,:j,:rank,NULL)');foreach($pairs as $i=>$pair)$ins->execute(['r'=>$round['id'],'p'=>$pair,'j'=>$judgeId,'rank'=>$ranks[$i]]);}
try{$round=tsRound($pdo,$roundId);if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$judgeId=(int)($_POST['judge_id']??0);$action=(string)($_POST['action']??'');$j=$pdo->prepare('SELECT id,judge_name FROM bdc_test_scoring_judges WHERE id=:j AND round_id=:r');$j->execute(['j'=>$judgeId,'r'=>$roundId]);$judge=$j->fetch();if(!$judge)throw new RuntimeException('Test judge not found.');if($action==='generate_judge'){if($round['round_type']==='final')tsFinal($pdo,$round,$judgeId);else tsHeats($pdo,$round,$judgeId);$notice=$judge['judge_name'].' random valid scores generated.';}elseif($action==='generate_all'){foreach($pdo->query('SELECT id FROM bdc_test_scoring_judges WHERE round_id='.(int)$roundId.' ORDER BY judge_order')->fetchAll(PDO::FETCH_COLUMN) as $id){if($round['round_type']==='final')tsFinal($pdo,$round,(int)$id);else tsHeats($pdo,$round,(int)$id);}$notice='All test judges generated valid random scores.';}}}catch(Throwable $e){$error=$e->getMessage();$round=$round??[];}
$judges=[];if($round){$s=$pdo->prepare("SELECT j.*,CASE WHEN :final=1 THEN (SELECT COUNT(*) FROM bdc_test_scoring_final_marks m WHERE m.round_id=j.round_id AND m.judge_id=j.id) ELSE (SELECT COUNT(*) FROM bdc_test_scoring_marks m WHERE m.round_id=j.round_id AND m.judge_id=j.id AND m.mark_type IN('yes','alt')) END done FROM bdc_test_scoring_judges j WHERE j.round_id=:r ORDER BY j.judge_order");$s->execute(['final'=>$round['round_type']==='final'?1:0,'r'=>$roundId]);$judges=$s->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Test Judge Simulator</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><meta http-equiv="refresh" content="5"></head><body class="bg-light"><div class="bg-danger text-white text-center fw-bold p-2">TEST ENGINE ONLY · RANDOM JUDGE SIMULATION · NEVER AVAILABLE TO LIVE JUDGES</div><main class="container py-4" style="max-width:1000px"><h1 class="h3">Automated Judge Simulator</h1><?php if($round):?><p><?=e($round['event_name'])?> · <?=e(ucwords(str_replace('_',' ',$round['division'])))?> · <?=e(ucfirst($round['round_type']))?></p><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($round):?><form method="post" class="mb-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="judge_id" value="<?=(int)($judges[0]['id']??0)?>"><button class="btn btn-primary" name="action" value="generate_all">Generate Scores for All Judges</button> <a class="btn btn-outline-secondary" href="./?round_id=<?=$roundId?>">Back to Test Round</a></form><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Judge</th><th>Scope</th><th>Progress</th><th></th></tr></thead><tbody><?php foreach($judges as $j):$scope=(string)$j['scoring_scope'];if($round['round_type']==='final'){$t=$pdo->prepare("SELECT COUNT(*) FROM bdc_test_scoring_final_pairs WHERE round_id=:r AND pairing_status='confirmed'");$t->execute(['r'=>$roundId]);$total=(int)$t->fetchColumn();}else{$t=$pdo->prepare("SELECT COUNT(*) FROM bdc_test_scoring_entries WHERE round_id=:r AND entry_status='active' AND (:scope='all' OR dance_role=:scope2)");$t->execute(['r'=>$roundId,'scope'=>$scope,'scope2'=>$scope]);$total=(int)$t->fetchColumn();}?><tr><td><strong><?=e($j['judge_name'])?></strong><?=(int)$j['is_chief']?' ★':''?></td><td><?=e(strtoupper($scope))?></td><td><?=(int)$j['done']?> / <?=$total?><div class="progress" style="height:7px"><div class="progress-bar" style="width:<?=$total?min(100,round((int)$j['done']*100/$total)):0?>%"></div></div></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input type="hidden" name="judge_id" value="<?=(int)$j['id']?>"><button class="btn btn-sm btn-outline-primary" name="action" value="generate_judge">Generate This Judge</button></form></td></tr><?php endforeach;?></tbody></table></div></div><p class="small text-muted mt-3">This screen refreshes every 5 seconds so you can keep it open while generating or editing test judge scores in other tabs.</p><?php endif;?></main></body></html>